ALTER TABLE "local_agent_callback_event" ADD CONSTRAINT "local_agent_callback_payload_valid" CHECK (("local_agent_callback_event"."kind" = 'heartbeat' and "local_agent_callback_event"."stage" is not null and "local_agent_callback_event"."stage" in ('started', 'brief_read', 'work_read', 'result_prepared') and "local_agent_callback_event"."artifact_name" is null and "local_agent_callback_event"."artifact_mime_type" is null and "local_agent_callback_event"."artifact_content" is null and "local_agent_callback_event"."artifact_bytes" is null and "local_agent_callback_event"."artifact_sha256" is null) or ("local_agent_callback_event"."kind" = 'artifact' and "local_agent_callback_event"."stage" is null and "local_agent_callback_event"."artifact_name" is not null and "local_agent_callback_event"."artifact_name" = 'synthetic-run-report.json' and "local_agent_callback_event"."artifact_mime_type" is not null and "local_agent_callback_event"."artifact_mime_type" = 'application/json' and "local_agent_callback_event"."artifact_content" is not null and octet_length("local_agent_callback_event"."artifact_content") between 1 and 16384 and "local_agent_callback_event"."artifact_bytes" is not null and "local_agent_callback_event"."artifact_bytes" = octet_length("local_agent_callback_event"."artifact_content") and "local_agent_callback_event"."artifact_sha256" is not null and "local_agent_callback_event"."artifact_sha256" ~ '^[0-9a-f]{64}$'));